from pathlib import Path
import csv,json
out=Path(__file__).resolve().parent
url='https://www.deloitte.com/content/dam/assets-zone1/southeast-asia/en/docs/industries/consumer/2026/sea-cb-2026-sea-automotive-consumer-study.pdf'
rows=[]
def add(q,page,n,items):
 for label,v in items:
  rows.append(dict(source_id='MS03',source_url=url,question=q,printed_page=page,pdf_page_1_based=page,country='Indonesia',sample_n=n,metric_label=label,published_percent=v,unit='percent of question-specific survey base',fieldwork='October–November 2025',rounding_note='Published rounded percentage; do not infer exact respondent count',causal_status='descriptive survey result',qa='Visually checked against rendered PDF 11 November 2026'))
add('Q16',33,629,[('Authorized/new vehicle dealer',80),('Independent/aftermarket facility',19),('I did it myself',1),('Other',0)])
add('Q17',33,618,[('Cost',7),('Trust',21),('Convenience (location/hours)',12),('Quality of work',23),('Customer experience',14),('Personal relationship with mechanic/technician',3),('Warranty coverage',18),('Complexity of work required',2)])
add('Q21',34,618,[('Customer service/treatment',28),('Communication while vehicle is serviced',4),('Explanation of service work performed',11),('Cost/price',8),('Transparency of pricing and work performed',32),('Convenient location',5),('Availability of appointment',0),('Online booking tool',0),('Speed of service',8),('Efficiency of check-in/check-out',3),('Access to temporary/loaner vehicle',1)])
add('Q22',35,629,[('Manufacturer/brand',24),('Dealership where I acquired vehicle',20),('Dealership where I normally service vehicle',46),('Finance provider',6),('None of the above',3)])
with (out/'deloitte_service_indonesia.csv').open('w',newline='',encoding='utf8') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
(out/'deloitte_service_indonesia.json').write_text(json.dumps(rows,indent=2))
case={'toyota_all':250431,'all_wholesales':803687,'toyota_electrified_estimated':33950,'electrified_wholesales':175144}
se=case['toyota_electrified_estimated']/case['electrified_wholesales'];sc=(case['toyota_all']-case['toyota_electrified_estimated'])/(case['all_wholesales']-case['electrified_wholesales']);mix=case['electrified_wholesales']/case['all_wholesales'];baseline=case['toyota_all']/case['all_wholesales'];delta=.10*(se-sc)
calcs=[{'calculation_id':'MC01','name':'Market-mix sensitivity','type':'case-based derived sensitivity, not forecast','inputs':case,'formula':'share = electrified_mix * within_electrified_share + (1-electrified_mix) * within_conventional_share','within_electrified_share':se,'within_conventional_share':sc,'base_all_share':baseline,'mix_shift_assumption_pp':10,'overall_share_change_pp':delta*100,'overall_share_after_sensitivity':baseline+delta,'source':'Supplied IBSC casebook exhibits 1–2; Toyota electrified volume estimated in case','limit':'Stable within-category shares are an assumption; neither Toyota forecast nor Auto2000 effect.'},
{'calculation_id':'MC02','name':'After-sales decomposition non-identifiability','type':'synthetic counterexample, not observed data','formula':'contribution index = cohort vehicles * jobs due * capture share * GP-per-job index','base':{'vehicles':100,'jobs_due':2,'capture':.8,'gp_index':1,'result':160},'mechanical_case':{'vehicles':100,'jobs_due':1.5,'capture':.8,'gp_index':1,'result':120},'defection_case':{'vehicles':100,'jobs_due':2,'capture':.6,'gp_index':1,'result':120},'finding':'Identical 25% decline can result from lower work due or lower capture; aggregate alone cannot distinguish them.','limit':'Illustrates identification under the stated arithmetic only; values are normalized assumptions.'},
{'calculation_id':'MC03','name':'Existing service channel migration','type':'synthetic counterexample, not observed data','formula':'incremental job GP = change in completed Auto2000 jobs * realized GP-per-job','assumptions':'100 existing completed jobs remain 100; channel mix alone shifts; job mix, discounts and direct costs unchanged','incremental_transaction_GP':0,'limit':'Potential cost savings and digital assistance are separate mechanisms, not assumed zero.'},
{'calculation_id':'MC04','name':'No dedicated home charger among EV intenders','type':'approximate arithmetic from rounded nested survey shares','formula':'.61 * (1-.54)','result_percent':.61*(1-.54)*100,'source':'MS02; 61% home-preferring EV intenders; 54% of that subset dedicated-access','limit':'Approximately 28.1% of all EV intenders under common-base interpretation lack dedicated access; shared access can be sufficient. Not inability to charge or lost demand.'},
{'calculation_id':'MC05','name':'Contribution break-even relationship','type':'symbolic threshold, no observed input values','formula':'required additional completed transactions = incremental program cost / net contribution per additional completed transaction','conditions':'Positive net contribution; include partner share, cannibalization, discounts and displaced capacity; align period and cost basis','limit':'No arbitrary cost, conversion, customer-base or margin value supplied; no ROI forecast.'}]
(out/'economic_calculations.json').write_text(json.dumps(calcs,indent=2))
assert abs((mix*se+(1-mix)*sc)-baseline)<1e-12
assert calcs[1]['base']['result']*.75==calcs[1]['mechanical_case']['result']==calcs[1]['defection_case']['result']
print('Deloitte records',len(rows),'case sensitivity pp',delta*100,'calculation assertions passed')
